'use strict';

var decompose = require( './../lib' );

var factors = [ 0, 0, 0, 0 ];
var initial = [ 3, 4, 2, 5 ];
var nf;
var j;

nf = decompose( 12, initial, factors, 1, 0 );

console.log( 'Sequence length: %d', 12 );
console.log( 'Number of factors: %d', nf );
console.log( 'Factors:' );
for ( j = 0; j < nf; j++ ) {
	console.log( '  %d', factors[ j+2 ] );
}
